<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Profil';?>
<div class="page-head"><div><p class="eyebrow">Konto</p><h1>Profil</h1></div></div>
<?php if(isset($_GET['saved'])):?><div class="alert success">Profil zapisano.</div><?php endif;?><?php if(($_GET['password']??'')==='saved'):?><div class="alert success">Hasło zmieniono. Pozostałe sesje zostały wylogowane.</div><?php elseif(($_GET['password']??'')==='error'):?><div class="alert danger">Nie udało się zmienić hasła. Sprawdź bieżące hasło i wymagane minimum 10 znaków.</div><?php endif;?><?php if(!empty($profile['force_password_change'])):?><div class="alert warn"><strong>Wymagana zmiana hasła.</strong> Ustaw własne hasło przed dalszą pracą.</div><?php endif;?>
<section class="card section-card"><h2>Dane profilu</h2><form method="post" class="grid compact-form"><?=Csrf::field()?><label>Imię<input name="first_name" maxlength="100" value="<?=Html::e($profile['first_name'])?>"></label><label>Nazwisko<input name="last_name" maxlength="100" value="<?=Html::e($profile['last_name'])?>"></label><label>E-mail<input name="email" type="email" maxlength="190" value="<?=Html::e($profile['email'])?>" required></label><label>Język<select name="language"><option value="pl" <?=$profile['language']==='pl'?'selected':''?>>Polski</option><option value="en" <?=$profile['language']==='en'?'selected':''?>>English</option></select></label><label>Strefa czasowa<input name="timezone" value="<?=Html::e($profile['timezone'])?>" list="timezones" required><datalist id="timezones"><?php foreach(['Europe/Warsaw','UTC','Europe/London','America/New_York','Asia/Tokyo'] as $tz):?><option value="<?=Html::e($tz)?>"><?php endforeach;?></datalist></label><label>Motyw<select name="theme"><option value="system" <?=$profile['theme']==='system'?'selected':''?>>Systemowy</option><option value="light" <?=$profile['theme']==='light'?'selected':''?>>Jasny</option><option value="dark" <?=$profile['theme']==='dark'?'selected':''?>>Ciemny</option></select></label><div class="form-action"><button class="button">Zapisz profil</button></div></form></section>
<section class="card section-card"><h2>Zmień hasło</h2><form method="post" action="<?=Html::e(Url::to('/profile/password'))?>" class="grid compact-form"><?=Csrf::field()?><label>Bieżące hasło<input type="password" name="current_password" required autocomplete="current-password"></label><label>Nowe hasło<input type="password" name="new_password" minlength="10" required autocomplete="new-password"></label><label>Powtórz nowe hasło<input type="password" name="confirm_password" minlength="10" required autocomplete="new-password"></label><div class="form-action"><button class="button">Zmień hasło</button></div></form></section>
